#!/usr/bin/env python3
"""ERRORS2 analysis (registration planned/ERRORS2_PREREG.md). Run from the repo root after planned/errors2_run.js.
Reads out/errors2/*.jsonl (S1 rows, and shared-error rows) and out/errors1/*.jsonl (A2 rows with independent errors, Study A),
prints the verdict on each registered prediction and writes planned/errors2_results_table.md."""
import glob, json, random
R2 = [json.loads(l) for f in sorted(glob.glob('out/errors2/*.jsonl')) for l in open(f) if l.strip()]
R1 = [json.loads(l) for f in sorted(glob.glob('out/errors1/*.jsonl')) for l in open(f) if l.strip()]
METROS = ('houston', 'dfw'); LEVELS = ('L0', 'L1', 'L2', 'L3', 'L4'); RHO = (0.5, 0.8, 0.95)
def pick(arm, m, lv, rho=0, shared=0, study=None):
    """{seed: v10}. Independent errors (rho 0): S1 from ERRORS2 Study D, A2 from ERRORS1 Study A."""
    if rho == 0 and arm == 'A2': S = [r for r in R1 if r['study'] == 'A' and r['arm'] == 'A2' and r['metro'] == m and r['level'] == lv]
    else: S = [r for r in R2 if r['arm'] == arm and r['metro'] == m and r['level'] == lv and r['rho'] == rho and r['shared'] == shared and (study is None or r['study'] == study)]
    return {r['seed']: r for r in S}
def cut(m, lv, rho=0, shared=0, seeds=None, ci=False, key='v10'):
    st = 'D' if rho == 0 else None
    s1 = pick('S1', m, lv, rho, shared, st); a2 = pick('A2', m, lv, rho, shared, st)
    ss = sorted(set(s1) & set(a2) & (set(seeds) if seeds else set(s1)))
    f = lambda s: 1 - sum(a2[x][key] for x in s) / sum(s1[x][key] for x in s) if s and sum(s1[x][key] for x in s) else float('nan')
    if not ci: return f(ss)
    g = random.Random(1); bs = sorted(f([g.choice(ss) for _ in ss]) for _ in range(2000)); return f(ss), bs[50], bs[1949], len(ss), sum(s1[x][key] for x in ss), sum(a2[x][key] for x in ss)
def cutA0(m, lv):   # ERRORS1 Study A: A2 vs A0 (filed heights), independent errors
    a0 = {r['seed']: r['v10'] for r in R1 if r['study'] == 'A' and r['arm'] == 'A0' and r['metro'] == m and r['level'] == lv}
    a2 = {r['seed']: r['v10'] for r in R1 if r['study'] == 'A' and r['arm'] == 'A2' and r['metro'] == m and r['level'] == lv}
    ss = sorted(set(a0) & set(a2)); return 1 - sum(a2[x] for x in ss) / sum(a0[x] for x in ss)
P = []
def chk(name, ok, text): P.append((name, ok, text)); print('PASS' if ok else 'FAIL', name, text)
both = lambda fn: {m: fn(m) for m in METROS}
fmt = lambda d: ', '.join(f'{m} {100 * v:.0f} %' for m, v in d.items())
D = {lv: both(lambda m, lv=lv: cut(m, lv)) for lv in LEVELS}
chk('D1', all(D['L1'][m] >= 0.60 for m in METROS), 'headline-case cut at L1: ' + fmt(D['L1']))
chk('D2', all(0.40 <= D['L2'][m] <= 0.65 for m in METROS), 'at L2: ' + fmt(D['L2']))
chk('D3', all(D['L4'][m] < 0.30 for m in METROS), 'at L4: ' + fmt(D['L4']))
rat = {lv: both(lambda m, lv=lv: (D[lv][m] / D['L0'][m], cutA0(m, lv) / cutA0(m, 'L0'))) for lv in ('L2', 'L4')}
chk('D4', all(abs(rat[lv][m][0] - rat[lv][m][1]) <= 0.15 for lv in rat for m in METROS), 'share of the no-error cut kept, headline case vs filed-heights case (ERRORS1): ' + '; '.join(f'{m} {lv} {rat[lv][m][0]:.2f} vs {rat[lv][m][1]:.2f}' for lv in rat for m in METROS))
chk('D5', all(D[LEVELS[i + 1]][m] <= D[LEVELS[i]][m] + 0.03 for i in range(4) for m in METROS), 'by level: ' + '; '.join(f'{m} ' + ' > '.join(f'{100 * D[lv][m]:.0f}' for lv in LEVELS) for m in METROS))
S4 = (1, 2, 3, 4)
eq = {lv: both(lambda m, lv=lv: (cut(m, lv, 0.8, 1, S4), cut(m, lv, 0.8, 0, S4))) for lv in ('L2', 'L4')}
chk('C1', all(abs(eq[lv][m][0] - eq[lv][m][1]) <= 0.05 for lv in eq for m in METROS), 'rho 0.8, seeds 1-4, shared field vs personal part only: ' + '; '.join(f'{m} {lv} {100 * eq[lv][m][0]:.0f} vs {100 * eq[lv][m][1]:.0f} %' for lv in eq for m in METROS))
C = {(lv, r): both(lambda m, lv=lv, r=r: cut(m, lv, r, 1)) for lv in ('L2', 'L4') for r in RHO}
seq = lambda m, lv: [D[lv][m]] + [C[(lv, r)][m] for r in RHO]
chk('C2', all(b >= a - 0.03 for lv in ('L2', 'L4') for m in METROS for a, b in zip(seq(m, lv), seq(m, lv)[1:])), 'cut as the shared share rises 0 > 0.5 > 0.8 > 0.95: ' + '; '.join(f'{m} {lv} ' + ' > '.join(f'{100 * v:.0f}' for v in seq(m, lv)) for lv in ('L2', 'L4') for m in METROS))
chk('C3', all(C[('L4', 0.95)][m] - D['L4'][m] >= 0.25 for m in METROS), 'L4, rho 0.95 minus independent: ' + fmt(both(lambda m: C[('L4', 0.95)][m] - D['L4'][m])))
chk('C4', all(abs(C[('L2', 0.8)][m] - D['L1'][m]) <= 0.10 for m in METROS), 'L2 rho 0.8 vs independent L1: ' + '; '.join(f'{m} {100 * C[("L2", 0.8)][m]:.0f} vs {100 * D["L1"][m]:.0f} %' for m in METROS))
chk('C5', all(abs(C[('L2', 0.95)][m] - D['L0'][m]) <= 0.06 for m in METROS), 'L2 rho 0.95 vs no errors: ' + '; '.join(f'{m} {100 * C[("L2", 0.95)][m]:.0f} vs {100 * D["L0"][m]:.0f} %' for m in METROS))
npass = sum(1 for _, ok, _ in P if ok)
L = ['# ERRORS2 results table (generated by planned/errors2_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Runs: {len(R2)} in out/errors2 (Study D {sum(r["study"] == "D" for r in R2)}, C {sum(r["study"] == "C" for r in R2)}, E {sum(r["study"] == "E" for r in R2)}); A2 rows with independent errors from ERRORS1.', '']
L += [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## Headline case (S1 vs A2): cut by error level, independent errors (pooled; 95 % bootstrap interval over seeds)', '', '| Metro | Level | Seeds | S1 conflicts | A2 conflicts | Cut [95 %] |', '|---|---|---|---|---|---|']
for m in METROS:
    for lv in LEVELS:
        f, lo, hi, n, a, b = cut(m, lv, ci=True); L.append(f'| {m} | {lv} | {n} | {a} | {b} | {100 * f:.0f} % [{100 * lo:.0f}-{100 * hi:.0f}] |')
L += ['', '## Shared errors: cut by the shared share of the error (rho), total size L2 and L4', '', '| Metro | Level | Shared share | Seeds | S1 conflicts | A2 conflicts | Cut [95 %] |', '|---|---|---|---|---|---|---|']
for m in METROS:
    for lv in ('L2', 'L4'):
        for r in (0,) + RHO:
            f, lo, hi, n, a, b = cut(m, lv, r, 0 if r == 0 else 1, ci=True); L.append(f'| {m} | {lv} | {r} | {n} | {a} | {b} | {100 * f:.0f} % [{100 * lo:.0f}-{100 * hi:.0f}] |')
L += ['', '## Equivalence arms (rho 0.8, seeds 1-4): shared field plus personal part vs personal part only', '', '| Metro | Level | With field: S1 / A2 / cut | Personal only: S1 / A2 / cut |', '|---|---|---|---|']
for m in METROS:
    for lv in ('L2', 'L4'):
        x = cut(m, lv, 0.8, 1, S4, True); y = cut(m, lv, 0.8, 0, S4, True); L.append(f'| {m} | {lv} | {x[4]} / {x[5]} / {100 * x[0]:.0f} % | {y[4]} / {y[5]} / {100 * y[0]:.0f} % |')
open('planned/errors2_results_table.md', 'w').write('\n'.join(L) + '\n'); print(f'{npass} of {len(P)} passed')
